//! Icônes engendrées hors ligne depuis les SVG. Ne pas modifier à la main.
//!
//! Chaque icône est une pile de couches, dans l'ordre d'empilement. Une
//! couche sans couleur est une pièce de structure : le rendu lui donne le
//! ton qui contraste avec la barre des tâches. Une couche colorée garde sa
//! teinte, puisqu'elle porte une information et non une décoration.
//!
//! Les pièces sont dessinées à chacune des quatre tailles que Windows
//! réclame selon la densité d'écran, plutôt que redimensionnées : réduire
//! une grille de 24 place les traits à cheval sur deux pixels.

/// Un masque d'opacité et, éventuellement, la couleur qui l'habille.
pub type Layer = (&'static [u8], Option<(u8, u8, u8)>);

